```python
import hashlib

# Định nghĩa hàm băm
def hash_function(password):
    return hashlib.md5(password.encode()).hexdigest()

# Tạo bảng cầu vồng
def create_rainbow_table(passwords, chain_length):
    rainbow_table = {}
    for password in passwords:
        chain = [password]
        for i in range(chain_length):
            hashed_password = hash_function(chain[-1])
            chain.append(hashed_password)
        rainbow_table[chain[-1]] = password
    return rainbow_table

# Tấn công bảng cầu vồng
def rainbow_table_attack(hashed_password, rainbow_table, chain_length):
    for i in range(chain_length):
        hashed_password = hash_function(hashed_password)
        if hashed_password in rainbow_table:
            return rainbow_table[hashed_password]
    return None

# Ví dụ sử dụng
passwords = ["matkhau1", "matkhau2", "matkhau3"]
chain_length = 1000
rainbow_table = create_rainbow_table(passwords, chain_length)

hashed_password = "băm_mật_khẩu_để_tấn_công"
tấn_công_thành_công = rainbow_table_attack(hashed_password, rainbow_table, chain_length)

if tấn_công_thành_công:
    print("Mật khẩu bị tấn công thành công:", tấn_công_thành_công)
else:
    print("Tấn công không thành công")
```

